xql_query:
// ============================================================
// Rule: THM_Browser Process with suspicious CommandLine
// Vendor: Windows
// Objective:
// Detect activity associated with THM_Browser Process with suspicious CommandLine.
// Severity: SEV_040_HIGH
// Category: EXECUTION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0002 - Execution
// Technique: T1059 - Command and Scripting Interpreter

// Desabilita diferenciação entre maiúsculas e minúsculas para comparações
config case_sensitive = false  

// Define o dataset de origem como dados brutos do Cortex XDR
| dataset = xdr_data  

// Filtra apenas eventos relacionados a processos
| filter event_type = ENUM.PROCESS  

// Restringe aos eventos de início de processo
| filter event_sub_type = ENUM.PROCESS_START  

// Foca apenas em navegadores específicos
| filter action_process_image_name in ("chrome.exe", "msedge.exe", "brave.exe", "opera.exe")  

// Identifica execução com parâmetros suspeitos associados a uso automatizado de navegadores
// Indicadores: execução em modo headless, sem GPU e sem sandbox
| filter (action_process_image_command_line contains "–headless" 
       and action_process_image_command_line contains "–disable-gpu" 
       and action_process_image_command_line contains "–no-sandbox")  

// Seleciona os campos relevantes para análise
| fields _time,                               // Momento do evento
         agent_hostname,                      // Nome do host onde ocorreu a execução
         actor_effective_username,            // Usuário efetivo que iniciou o processo
         causality_actor_process_image_path,  // Caminho do processo raiz na cadeia causal
         actor_process_image_path,            // Caminho completo do processo iniciado
         actor_process_image_sha256,          // Hash SHA256 do binário do processo
         action_process_image_command_line    // Linha de comando usada na execução
